select format('alembic=%s ledger=%s telemetry=%s events=%s alerts=%s users=%s farms=%s devices=%s audit=%s rejected=%s', (select version_num from alembic_version), (select count(*) from ingested_messages), (select count(*) from telemetry), (select count(*) from device_events), (select count(*) from alerts), (select count(*) from users), (select count(*) from farms), (select count(*) from devices), (select count(*) from audit_log), (select count(*) from rejected_messages));
select 'content md5: ledger=' || (select md5(string_agg(msg_id || kind || seq::text || device_ts::text, ',' order by msg_id)) from ingested_messages) || ' telemetry=' || (select md5(string_agg(msg_id || time::text || battery_pct::text, ',' order by msg_id)) from telemetry) || ' alerts=' || (select md5(string_agg(source_msg_id || alert_type, ',' order by source_msg_id, alert_type)) from alerts) || ' users=' || (select md5(string_agg(phone, ',' order by phone)) from users);
select 'hypertables: ' || string_agg(hypertable_name || ' chunks=' || num_chunks, ', ' order by hypertable_name) from timescaledb_information.hypertables;
select 'timescaledb ' || extversion || ', restoring=' || current_setting('timescaledb.restoring') from pg_extension where extname='timescaledb';
